import React from 'react';
import { 
  LayoutDashboard, 
  Users, 
  BarChart2, 
  Bot, 
  Store, 
  FileText, 
  Settings, 
  HelpCircle 
} from 'lucide-react';
import { motion } from 'framer-motion';
import { cn } from '../../lib/utils';
import { Tooltip, TooltipContent, TooltipTrigger } from './ui/tooltip';

interface NavItemProps {
  icon: React.ElementType;
  label: string;
  isActive?: boolean;
}

const NavItem = ({ icon: Icon, label, isActive }: NavItemProps) => {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <motion.div 
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={cn(
            "flex items-center justify-center w-12 h-12 rounded-xl transition-all duration-300 cursor-pointer group mx-auto",
            isActive 
              ? "bg-secondary text-foreground shadow-elevation-sm" 
              : "text-base-second hover:bg-secondary/50 hover:text-foreground"
          )}
        >
          <Icon size={22} strokeWidth={1.5} className="opacity-90" />
        </motion.div>
      </TooltipTrigger>
      <TooltipContent side="right" className="ml-2 font-medium">
        <p>{label}</p>
      </TooltipContent>
    </Tooltip>
  );
};

